(() => {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const locale = {'320 × 360 · interactive preview':'320 × 360 · 交互预览','DIRECTOR PANEL':'导演面板','Zing! Watch':'Zing! 手表','Live copy + color controls':'实时修改文案和色块','Screen':'界面','Hello / home':'首页','Wake':'唤醒','Meet':'遇见','Ask':'提问','Shadow hop':'影子游戏','My Things':'我的朋友','Explorer Club':'探索小组','Friend Map':'朋友地图','Tiny Note':'小提示','Reset demo content':'重置内容','Hi, 小安':'小安，你好','Find a tiny friend':'发现一个小朋友','拍一张，让它醒来':'拍一张，让它醒来','Wake a friend':'唤醒朋友','唤醒朋友':'唤醒朋友','Ask a thing':'问一个东西','问问它':'问问它','我的朋友':'我的朋友','探索小组':'探索小组','小提示':'小提示','hold still…':'保持不动…','点一下，让它醒来':'点一下，让它醒来','Wake it up':'让它醒来','Peek closer!':'再靠近一点','I think it’s moving!':'它好像动了！','Meet Leafy':'遇见小叶','Leafy':'小叶','Grow Garden · 自然角':'生长花园','My secret':'我的秘密','I wear a tiny green cape.':'我有一件绿色小斗篷。','Tiny true thing':'一个小事实','My lines carry water.':'我的叶脉会运水。','Let’s try!':'试试看','Can you trace one line?':'找到一条叶脉。','Wonder together':'一起想想','Ask Leafy':'问问小叶','What are you curious about?':'你想知道什么？','How do you drink?':'我怎么喝水？','Why are you green?':'我为什么是绿色？','What should I look for?':'我该找什么？','Tap a question.':'点一个问题。','Try it outside':'去外面试试','Trace Leafy’s line':'找到小叶的叶脉','用手指找一条叶脉':'用手指找一条叶脉','I found it!':'我找到了！','Friends I’ve met':'我认识的朋友','每个朋友都会继续长大':'每个朋友都会长大','visited today · Grow Garden':'今天见过 · 生长花园','come back when it rains':'下雨时再来看','Find another':'再找一个','Someone in your safe circle':'安全圈里有人','woke a tiny snail!':'唤醒了一只小蜗牛！','送一颗 sparkle':'送一颗星星','Cloudy found a new shape':'云朵找到了新形状','yesterday · safe circle':'昨天 · 安全圈','Grow':'生长','Garden':'花园','Wiggle':'扭扭','Woods':'树林','Sky':'天空','Club':'俱乐部','Make-It':'动手','Market':'小市集','Find something':'找一个','that looks like a monster.':'看起来像怪兽的东西。','今天，去外面看看。':'今天去外面看看。','I found one!':'我找到了！','Send sparkle':'送一颗星星','Sparkle sent':'星星已送出','Reset demo content':'重置内容'};
  function localize(){ $$('*').forEach(el=>{if(el.children.length===0){const t=el.textContent.trim();if(locale[t])el.textContent=locale[t]}}); const holder=$('.home-hello'); if(holder&&!holder.querySelector('.greeting')){let name=localStorage.getItem('zing-name');if(!name){name=prompt('我应该怎么称呼你？','ada')||'ada';localStorage.setItem('zing-name',name)}const greeting=document.createElement('span');greeting.className='greeting';greeting.textContent='你好，'+name;holder.prepend(greeting);holder.addEventListener('click',()=>{const next=prompt('换一个称呼？',name);if(next){name=next;localStorage.setItem('zing-name',name);greeting.textContent='你好，'+name}});} }
  function go(name){$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));$('#screenSelect').value=name==='loading'?'wake':name;renderCopy(name==='loading'?'wake':name)}
  function renderCopy(name){const wrap=$('#copyFields');wrap.innerHTML='';const view=$(`[data-view="${name}"]`);if(view){const targets=[...view.querySelectorAll('h2,h3,strong,small,p,button')].filter(el=>el.children.length===0&&el.textContent.trim());targets.forEach((el,i)=>{const label=document.createElement('label');label.textContent=`文案 ${i+1}`;const field=document.createElement('textarea');field.rows=2;field.value=el.textContent.trim();field.addEventListener('input',()=>{el.textContent=field.value});label.appendChild(field);wrap.appendChild(label)})}}
  function renderColors(){const wrap=$('.color-fields');wrap.innerHTML='';const targets=$$('.tile,.home-lead,.story-block,.ask-choice,.friend-card,.club-card,.map-place,.note-card,.big-cta');targets.forEach((el,i)=>{const label=document.createElement('label');label.textContent=`色块 ${i+1}`;const input=document.createElement('input');input.type='color';input.value=getComputedStyle(el).backgroundColor.match(/\d+/g)?.slice(0,3).reduce((h,n)=>h+Number(n).toString(16).padStart(2,'0'),'#')||'#ffffff';input.addEventListener('input',()=>{el.style.background=input.value});label.appendChild(input);wrap.appendChild(label)})}
  $$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
  $('#screenSelect')?.addEventListener('change',e=>go(e.target.value));
  $('[data-action="capture"]')?.addEventListener('click',()=>{ const img=$('#photoPreview'); img.src='assets/pixel-world.jpg'; img.classList.add('ready'); $('#avatarImage').src=img.src; $('#askAvatar').src=img.src; $('#collectionAvatar')?.setAttribute('src',img.src); $('#photoFrame').classList.add('captured'); $('.chat-cta').disabled=false; });
  $('[data-action="import"]')?.addEventListener('click',()=>$('#photoInput').click());
  $('#photoInput')?.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;const url=URL.createObjectURL(file);$('#photoPreview').src=url;$('#photoPreview').classList.add('ready');$('#avatarImage').src=url;$('#askAvatar').src=url;$('#collectionAvatar')?.setAttribute('src',url);$('#photoFrame').classList.add('captured');$('.chat-cta').disabled=false});
  $$('[data-answer]').forEach(b=>b.addEventListener('click',()=>{ $$('.inline-answer').forEach(x=>{x.classList.remove('open');x.textContent=''});const answer=b.nextElementSibling;if(answer&&answer.classList.contains('inline-answer')){answer.textContent=b.dataset.answer;answer.classList.add('open')} }));
  $('[data-action="collect"]')?.addEventListener('click',()=>{const b=$('[data-action="collect"]');b.textContent='已收藏 · 自然 +1 ✦';b.classList.add('collected');const card=$('.friend-card');if(card&&!card.querySelector('.friend-tag')){const tag=document.createElement('em');tag.className='friend-tag';tag.textContent='自然';card.appendChild(tag)}setTimeout(()=>go('things'),300)});
  $$('[data-action="name"]').forEach(button=>button.addEventListener('click',()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){const name=prompt('它叫什么？','小甲');if(name)$('[data-copy="name"]').textContent=name;return}const r=new Speech();r.lang='zh-CN';r.onresult=e=>{const name=e.results[0][0].transcript.trim();$$('[data-copy="name"]').forEach(el=>el.textContent=name||'小甲')};r.start()}));
  $('[data-action="speak"]')?.addEventListener('click',()=>{const text=$('[data-copy="intro"]').textContent;if('speechSynthesis' in window)window.speechSynthesis.speak(new SpeechSynthesisUtterance(text))});
  $$('[data-action="sparkle"]').forEach(b=>b.addEventListener('click',()=>{ $('[data-sparkle]')?.classList.add('show');b.textContent='星星已送出'}));
  $$('[data-color]').forEach(i=>i.addEventListener('input',()=>document.documentElement.style.setProperty(`--${i.dataset.color}`,i.value)));
  $('#screenSelect')?.addEventListener('change',()=>renderColors());$('#resetPanel')?.addEventListener('click',()=>location.reload());localize();renderColors();go('home');
})();
  function updateNewFriend(){
    document.querySelectorAll('[data-copy="home"]').forEach(el=>el.textContent='今天见过');
    document.querySelectorAll('.ask-friend-head small').forEach(el=>el.textContent='今天见过');
    const things=document.querySelector('[data-view="things"]');
    if(things){things.innerHTML='<div class="view-head"><button data-go="home">‹</button><b>我的朋友</b><span>✦ 1</span></div><div class="section-intro"><strong>我认识的朋友</strong><small>每个朋友都会继续长大</small></div><button class="friend-card mint-bg" data-go="meet"><div class="photo-avatar collection-avatar"><img id="collectionAvatar" alt="小甲的照片"><div class="avatar-eyes"><i></i><i></i></div></div><span><b>小甲</b><small>今天见过</small></span><em>›</em><label class="category-tag">自然</label></button><button class="big-cta lemon-bg" data-go="home">回到首页 <span>→</span></button>';
      things.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===b.dataset.go))}));
      const avatar=document.querySelector('#avatarImage');const collection=document.querySelector('#collectionAvatar');if(avatar&&collection&&avatar.src)collection.src=avatar.src;
    }
  }
  updateNewFriend();
